{
  "bioavailability_prediction": "high",
  "confidence": "moderate",
  "revision_action": "strengthen",
  "supportive_card_ids": ["C10","C07","C05","C21","C26","C24","C18","C20","C15","C25","C27","C16","C17","C19","C28","C30","C32","C38"],
  "contradictory_card_ids": [],
  "prediction_basis_card_ids": ["C10","C07","C05","C21","C26","C24","C18","C20","C15","C25","C27"],
  "claims": [
    {
      "claim": "The query is a polar guanine carbocyclic nucleoside analog; the closest L1 human nucleoside records all report absolute oral bioavailability above 20%: zalcitabine 80% in fasted patients (C10), ddA/ddl 38% in fasting patients (C07), and OGT719 about 25% in patients (C05).",
      "card_ids": ["C10","C07","C05"]
    },
    {
      "claim": "L2 records add further nucleoside/nucleobase-analog F values above the 20% threshold: zalcitabine 30% in fasted mice (C21), ddI 30-54% (C26), compound 109 30% in mice (C24), compound 19 63% in rats and 71% in dogs (C18, C20), evogliptin 50% in healthy individuals (C15) and 74.8% in rats (C25), and seletracetam about 92% (C27); qualitative reports also describe good/complete oral bioavailability for nevirapine (C16, C17) and compound 109 (C19).",
      "card_ids": ["C21","C26","C24","C18","C20","C15","C25","C27","C16","C17","C19"]
    },
    {
      "claim": "L3 oral exposure records show rapid absorption and measurable systemic exposure for nucleoside analogs: lamivudine Tmax 0.75-1.26 h and Cmax 3.3 µg/mL (C30, C32, C28, C34), penciclovir after oral famciclovir Cmax about 3.4-3.45 µg/mL (C33, C36), adefovir after FDC Tmax 1 h (C29), and lamivudine AUC0-12 5522.7 ng·h/mL (C38). These are consistent with oral absorption but do not directly quantify F.",
      "card_ids": ["C28","C29","C30","C31","C32","C33","C34","C35","C36","C37","C38","C39"]
    },
    {
      "claim": "No transferable record affirmatively supports F <20%; the low/poor oral bioavailability records for cefepime (C14, C23) come from a cephalosporin context with low transferability to a guanine nucleoside and do not provide affirmative evidence for the query.",
      "card_ids": ["C14","C23"]
    },
    {
      "claim": "The physicochemical prior (low logP, high TPSA) is a permeability concern but not endpoint proof; the modest 20% threshold and the consistent empirical direction from nucleoside analogs support a high prediction.",
      "card_ids": ["C10","C07","C05"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "oral_auc_cmax_exposure",
      "applicability": "moderate",
      "direction": "supportive",
      "decision_effect": "strengthened",
      "card_ids": ["C28","C29","C30","C31","C32","C33","C34","C35","C36","C37","C38","C39"]
    }
  ],
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for the exact query molecule.",
    "L3 records are exposure metrics (Tmax/Cmax/AUC) without IV comparison, so they do not quantify F.",
    "Some L3 records involve prodrugs (famciclovir, adefovir dipivoxil), limiting transferability to the non-prodrug query.",
    "No explicit evidence of nucleoside transporter involvement or metabolic stability for the query.",
    "Fasted-state human data for the exact query are absent; closest fasting data are C10 (tablet) and C07 (solution with antacid).",
    "C05 shows considerable interpatient variability and no fasting condition, limiting precision of analog transfer."
  ],
  "decision_summary": "Prediction high: the most relevant L1 human nucleoside records (zalcitabine 80%, ddA/ddl 38%, OGT719 ~25%) and L2 nucleoside analog F values all exceed 20%; L3 oral exposure records for lamivudine and related nucleoside analogs are consistent with oral absorption and do not contradict. No transferable record affirmatively supports F<20%; confidence remains moderate because the exact query lacks direct F data."
}

